import hashlib
import json


def build_golden(items):
    kanonisch = json.dumps(sorted(items, key=lambda e: e["id"]), sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    return {"n": len(items), "ids": sorted(e["id"] for e in items), "sha256": hashlib.sha256(kanonisch.encode("utf-8")).hexdigest()}

